"<!DOCTYPE html>
<html lang=\"uk\">
<head>
<meta charset=\"UTF-8\">
<title>Бодування в Ємені — 3D</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { overflow: hidden; font-family: 'Segoe UI', sans-serif; background: #000; }
  canvas { display: block; }

  #ui {
    position: absolute; top: 15px; left: 15px;
    background: rgba(20, 15, 10, 0.85);
    color: #f5e6c8; padding: 15px 20px; border-radius: 12px;
    border: 2px solid #c9a227; backdrop-filter: blur(6px);
    box-shadow: 0 4px 20px rgba(0,0,0,0.6);
    min-width: 240px; user-select: none;
  }
  #ui h2 { color: #c9a227; font-size: 16px; margin-bottom: 10px; letter-spacing: 1px; }
  #ui .stat { display: flex; justify-content: space-between; margin: 6px 0; font-size: 14px; }
  #ui .stat b { color: #ffd75e; }

  #tools {
    position: absolute; bottom: 20px; left: 50%;
    transform: translateX(-50%);
    display: flex; gap: 10px; background: rgba(20, 15, 10, 0.85);
    padding: 12px; border-radius: 14px; border: 2px solid #c9a227;
    backdrop-filter: blur(6px); flex-wrap: wrap; justify-content: center;
    max-width: 95vw;
  }
  .tool {
    width: 70px; height: 70px; border-radius: 10px; cursor: pointer;
    background: rgba(60, 45, 30, 0.9); border: 2px solid #7a5c2e;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    color: #f5e6c8; font-size: 11px; transition: all 0.15s; user-select: none;
  }
  .tool:hover { background: rgba(90, 70, 40, 0.9); transform: translateY(-3px); }
  .tool.active { border-color: #ffd75e; background: rgba(201, 162, 39, 0.4); box-shadow: 0 0 15px #c9a227; }
  .tool .icon { font-size: 26px; margin-bottom: 3px; }

  #info {
    position: absolute; top: 15px; right: 15px;
    background: rgba(20, 15, 10, 0.85); color: #f5e6c8;
    padding: 12px 18px; border-radius: 10px; border: 2px solid #c9a227;
    font-size: 13px; max-width: 220px; backdrop-filter: blur(6px);
  }
  #info b { color: #c9a227; }

  #crosshair {
    position: absolute; top: 50%; left: 50%;
    width: 20px; height: 20px; transform: translate(-50%, -50%);
    pointer-events: none; opacity: 0.8;
  }
  #crosshair::before, #crosshair::after {
    content: ''; position: absolute; background: #ffd75e;
  }
  #crosshair::before { width: 2px; height: 20px; left: 9px; top: 0; }
  #crosshair::after { width: 20px; height: 2px; left: 0; top: 9px; }

  #msg {
    position: absolute; top: 30%; left: 50%; transform: translateX(-50%);
    background: rgba(0,0,0,0.8); color: #ffd75e; padding: 10px 25px;
    border-radius: 8px; font-size: 16px; opacity: 0;
    transition: opacity 0.4s; pointer-events: none;
  }
  #msg.show { opacity: 1; }
</style>
</head>
<body>

<div id=\"ui\">
  <h2>🏜️ БОДУВАННЯ В ЄМЕНІ</h2>
  <div class=\"stat\"><span>💰 Гроші:</span><b id=\"money\">5000</b></div>
  <div class=\"stat\"><span>🏠 Будівлі:</span><b id=\"buildings\">0</b></div>
  <div class=\"stat\"><span>👥 Населення:</span><b id=\"pop\">0</b></div>
  <div class=\"stat\"><span>😊 Щастя:</span><b id=\"happy\">100%</b></div>
</div>

<div id=\"tools\">
  <div class=\"tool active\" data-type=\"house\"><div class=\"icon\">🏠</div>Хата<br>₴200</div>
  <div class=\"tool\" data-type=\"tower\"><div class=\"icon\">🕌</div>Мінарет<br>₴800</div>
  <div class=\"tool\" data-type=\"shop\"><div class=\"icon\">🏪</div>Базар<br>₴400</div>
  <div class=\"tool\" data-type=\"tree\"><div class=\"icon\">🌴</div>Пальма<br>₴50</div>
  <div class=\"tool\" data-type=\"well\"><div class=\"icon\">⛲</div>Криниця<br>₴150</div>
  <div class=\"tool\" data-type=\"delete\"><div class=\"icon\">🗑️</div>Знести</div>
</div>

<div id=\"info\">
  <b>🖱️ Керування:</b><br>
  ЛКМ — будувати<br>
  ПКМ — огляд (обертати)<br>
  Колесо — зум<br>
  WASD — переміщення<br>
  <br>
  <b>🎯 Мета:</b> збудуй квітуче місто!
</div>

<div id=\"crosshair\"></div>
<div id=\"msg\"></div>

<script type=\"importmap\">
{
  \"imports\": {
    \"three\": \"https://unpkg.com/three@0.160.0/build/three.module.js\",
    \"three/addons/\": \"https://unpkg.com/three@0.160.0/examples/jsm/\"
  }
}
</script>

<script type=\"module\">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ═══════════ СЦЕНА ═══════════
const scene = new THREE.Scene();
scene.background = new THREE.Color(0xd4b88a);
scene.fog = new THREE.Fog(0xd4b88a, 60, 180);

const camera = new THREE.PerspectiveCamera(60, innerWidth/innerHeight, 0.1, 1000);
camera.position.set(30, 35, 40);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
document.body.appendChild(renderer.domElement);

// ═══════════ ОСВІТЛЕННЯ (реалістичне, спекотний Ємен) ═══════════
const hemi = new THREE.HemisphereLight(0xffe4b5, 0x8b6f47, 0.7);
scene.add(hemi);

const sun = new THREE.DirectionalLight(0xfff2cc, 2.2);
sun.position.set(50, 80, 30);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -80;
sun.shadow.camera.right = 80;
sun.shadow.camera.top = 80;
sun.shadow.camera.bottom = -80;
sun.shadow.camera.near = 0.5;
sun.shadow.camera.far = 250;
sun.shadow.bias = -0.0005;
scene.add(sun);

const fill = new THREE.DirectionalLight(0xffcc88, 0.4);
fill.position.set(-30, 20, -30);
scene.add(fill);

// ═══════════ ЗЕМЛЯ ═══════════
const groundGeo = new THREE.PlaneGeometry(200, 200, 100, 100);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0xc9a876, roughness: 0.95, metalness: 0.0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI/2;
ground.receiveShadow = true;
scene.add(ground);

// Піщана текстура (процедурна)
const canvas = document.createElement('canvas');
canvas.width = canvas.height = 512;
const ctx = canvas.getContext('2d');
ctx.fillStyle = '#c9a876';
ctx.fillRect(0, 0, 512, 512);
for (let i = 0; i < 3000; i++) {
  const x = Math.random()*512, y = Math.random()*512;
  const r = Math.random()*3;
  ctx.fillStyle = `rgba(${150+Math.random()*60},${120+Math.random()*50},${70+Math.random()*40},0.6)`;
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
}
const sandTex = new THREE.CanvasTexture(canvas);
sandTex.wrapS = sandTex.wrapT = THREE.RepeatWrapping;
sandTex.repeat.set(25, 25);
groundMat.map = sandTex;
groundMat.needsUpdate = true;

// ═══════════ СІТКА для будівництва ═══════════
const GRID = 4;
const SIZE = 16;
const gridHelper = new THREE.GridHelper(SIZE*GRID, SIZE, 0x8b6f47, 0xaa8f5f);
gridHelper.position.y = 0.02;
gridHelper.material.opacity = 0.3;
gridHelper.material.transparent = true;
scene.add(gridHelper);

// ═══════════ КЕРУВАННЯ ═══════════
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.maxPolarAngle = Math.PI/2.2;
controls.minDistance = 15;
controls.maxDistance = 120;
controls.target.set(0, 0, 0);
controls.mouseButtons = {
  LEFT: null,
  MIDDLE: THREE.MOUSE.DOLLY,
  RIGHT: THREE.MOUSE.ROTATE
};

// ═══════════ СТАН ГРИ ═══════════
let money = 5000;
let population = 0;
let happiness = 100;
const buildingsList = [];
let currentTool = 'house';
let ghost = null;

const COSTS = { house: 200, tower: 800, shop: 400, tree: 50, well: 150, delete: 0 };
const POP = { house: 4, tower: 0, shop: 2, tree: 0, well: 0, delete: 0 };

// ═══════════ МАТЕРІАЛИ (реалістичні кольори Ємену) ═══════════
const MAT = {
  adobe: new THREE.MeshStandardMaterial({ color: 0xd4a574, roughness: 0.9 }),
  adobeDark: new THREE.MeshStandardMaterial({ color: 0xb88858, roughness: 0.9 }),
  white: new THREE.MeshStandardMaterial({ color: 0xf0e6d2, roughness: 0.7 }),
  wood: new THREE.MeshStandardMaterial({ color: 0x6b4423, roughness: 0.8 }),
  woodLight: new THREE.MeshStandardMaterial({ color: 0x8b5a2b, roughness: 0.8 }),
  gold: new THREE.MeshStandardMaterial({ color: 0xc9a227, roughness: 0.4, metalness: 0.6 }),
  green: new THREE.MeshStandardMaterial({ color: 0x4a7c3f, roughness: 0.9 }),
  palm: new THREE.MeshStandardMaterial({ color: 0x2d6b2d, roughness: 0.85 }),
  trunk: new THREE.MeshStandardMaterial({ color: 0x8b6f47, roughness: 0.95 }),
  water: new THREE.MeshStandardMaterial({ color: 0x3a7ca5, roughness: 0.1, metalness: 0.3, transparent: true, opacity: 0.85 }),
  red: new THREE.MeshStandardMaterial({ color: 0xa83232, roughness: 0.8 }),
  blue: new THREE.MeshStandardMaterial({ color: 0x2a5c8a, roughness: 0.8 })
};

// ═══════════ ФУНКЦІЇ БУДІВНИЦТВА ═══════════
function buildHouse() {
  const g = new THREE.Group();
  // Основа — традиційний єменський будинок
  const base = new THREE.Mesh(new THREE.BoxGeometry(3, 4, 3), MAT.adobe);
  base.position.y = 2; base.castShadow = base.receiveShadow = true;
  g.add(base);
  // Верхній поверх (вужчий)
  const top = new THREE.Mesh(new THREE.BoxGeometry(2.4, 2, 2.4), MAT.adobeDark);
  top.position.y = 5; top.castShadow = top.receiveShadow = true;
  g.add(top);
  // Вікна (білі рамки)
  for (let i = 0; i < 2; i++) {
    const win = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.8, 0.1), MAT.white);
    win.position.set(-0.6 + i*1.2, 2.8, 1.51);
    g.add(win);
  }
  // Двері
  const door = new THREE.Mesh(new THREE.BoxGeometry(0.8, 1.6, 0.1), MAT.wood);
  door.position.set(0, 0.8, 1.51);
  g.add(door);
  // Декоративна смуга
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(3.1, 0.15, 3.1), MAT.white);
  stripe.position.y = 3.9; g.add(stripe);
  // Плоский дах з зубцями
  for (let i = 0; i < 4; i++) {
    const zub = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.5, 0.3), MAT.adobeDark);
    zub.position.set(-1.2 + i*0.8, 6.25, -1.2);
    zub.castShadow = true;
    g.add(zub);
  }
  return g;
}

function buildTower() {
  const g = new THREE.Group();
  // Мінарет
  const base = new THREE.Mesh(new THREE.BoxGeometry(1.6, 7, 1.6), MAT.white);
  base.position.y = 3.5; base.castShadow = base.receiveShadow = true;
  g.add(base);
  // Балкон
  const balc = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.3, 2.2), MAT.adobeDark);
  balc.position.y = 7; balc.castShadow = true;
  g.add(balc);
  // Верхня частина
  const top = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 0.8, 3, 8), MAT.white);
  top.position.y = 8.6; top.castShadow = true;
  g.add(top);
  // Купол
  const dome = new THREE.Mesh(new THREE.SphereGeometry(0.8, 16, 12, 0, Math.PI*2, 0, Math.PI/2), MAT.gold);
  dome.position.y = 10.1; dome.castShadow = true;
  g.add(dome);
  // Півмісяць
  const moon = new THREE.Mesh(new THREE.TorusGeometry(0.25, 0.06, 8, 20), MAT.gold);
  moon.position.y = 11; moon.rotation.x = Math.PI/2;
  g.add(moon);
  // Вікна
  for (let i = 0; i < 3; i++) {
    const w = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.6, 0.1), MAT.blue);
    w.position.set(0, 2 + i*2, 0.81);
    g.add(w);
  }
  return g;
}

function buildShop() {
  const g = new THREE.Group();
  // Базар
  const base = new THREE.Mesh(new THREE.BoxGeometry(3.5, 2.5, 3), MAT.adobe);
  base.position.y = 1.25; base.castShadow = base.receiveShadow = true;
  g.add(base);
  // Навіс — смугастий тен
  for (let i = 0; i < 5; i++) {
    const stripe = new THREE.Mesh(
      new THREE.BoxGeometry(3.6, 0.08, 0.6),
      i % 2 === 0 ? MAT.red : MAT.white
    );
    stripe.position.set(0, 2.6, -1.2 + i*0.6);
    stripe.rotation.x = -0.15;
    g.add(stripe);
  }
  // Стовпи
  for (let x of [-1.5, 1.5]) for (let z of [-1.3, 1.3]) {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 2.6, 8), MAT.wood);
    pole.position.set(x, 1.3, z);
    pole.castShadow = true;
    g.add(pole);
  }
  // Товари
  for (let i = 0; i < 3; i++) {
    const box = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.4, 0.5),
      [MAT.green, MAT.red, MAT.gold][i]);
    box.position.set(-1 + i*1, 2.85, 0.5);
    g.add(box);
  }
  return g;
}

function buildTree() {
  const g = new THREE.Group();
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.25, 3, 8), MAT.trunk);
  trunk.position.y = 1.5; trunk.castShadow = true;
  g.add(trunk);
  for (let i = 0; i < 6; i++) {
    const angle = (i/6)*Math.PI*2;
    const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.35, 2.5, 4), MAT.palm);
    leaf.position.set(Math.cos(angle)*0.8, 3.2, Math.sin(angle)*0.8);
    leaf.rotation.z = Math.cos(angle)*0.9;
    leaf.rotation.x = Math.sin(angle)*0.9;
    leaf.castShadow = true;
    g.add(leaf);
  }
  return g;
}

function buildWell() {
  const g = new THREE.Group();
  const base = new THREE.Mesh(new THREE.CylinderGeometry(1, 1.1, 0.8, 16), MAT.adobeDark);
  base.position.y = 0.4; base.castShadow = base.receiveShadow = true;
  g.add(base);
  const water = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 0.8, 0.1, 16), MAT.water);
  water.position.y = 0.75;
  g.add(water);
  // Арка
  for (let x of [-0.8, 0.8]) {
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 2, 8), MAT.wood);
    post.position.set(x, 1.6, 0); post.castShadow = true;
    g.add(post);
  }
  const top = new THREE.Mesh(new THREE.BoxGeometry(2, 0.15, 0.15), MAT.wood);
  top.position.y = 2.6; top.castShadow = true;
  g.add(top);
  const roof = new THREE.Mesh(new THREE.ConeGeometry(1.2, 0.6, 4), MAT.red);
  roof.position.y = 2.9; roof.rotation.y = Math.PI/4; roof.castShadow = true;
  g.add(roof);
  return g;
}

const BUILDERS = { house: buildHouse, tower: buildTower, shop: buildShop, tree: buildTree, well: buildWell };

// ═══════════ ПРИВ'ЯЗКА ДО СІТКИ ═══════════
const occupied = new Set();
function key(x, z) { return `${Math.round(x/GRID)},${Math.round(z/GRID)}`; }

function snap(v) { return Math.round(v/GRID)*GRID; }

// ═══════════ GHOST (привид будівлі) ═══════════
function updateGhost(type) {
  if (ghost) { scene.remove(ghost); ghost = null; }
  if (type === 'delete') return;
  ghost = BUILDERS[type]();
  ghost.traverse(o => { if (o.material) { o.material = o.material.clone(); o.material.transparent = true; o.material.opacity = 0.5; }});
  ghost.visible = false;
  scene.add(ghost);
}

// ═══════════ РЕЙКАСТЕР ═══════════
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();
const plane = new THREE.Plane(new THREE.Vector3(0,1,0), 0);
const point = new THREE.Vector3();

function getGroundPoint(clientX, clientY) {
  mouse.x = (clientX / innerWidth) * 2 - 1;
  mouse.y = -(clientY / innerHeight) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);
  raycaster.ray.intersectPlane(plane, point);
  return point;
}

// ═══════════ ПОДІЇ МИШІ ═══════════
let dragging = false, downPos = {x:0,y:0};

renderer.domElement.addEventListener('pointerdown', e => {
  if (e.button === 0) { dragging = true; downPos = {x: e.clientX, y: e.clientY}; }
});
renderer.domElement.addEventListener('pointerup', e => {
  if (e.button !== 0) return;
  const moved = Math.hypot(e.clientX - downPos.x, e.clientY - downPos.y);
  dragging = false;
  if (moved > 5) return; // було обертання
  tryBuildOrDelete(e.clientX, e.clientY);
});

renderer.domElement.addEventListener('contextmenu', e => e.preventDefault());

renderer.domElement.addEventListener('pointermove', e => {
  const p = getGroundPoint(e.clientX, e.clientY);
  if (!p || !ghost) return;
  const sx = snap(p.x), sz = snap(p.z);
  // Обмеження в межах сітки
  const half = SIZE/2*GRID;
  const cx = Math.max(-half, Math.min(half, sx));
  const cz = Math.max(-half, Math.min(half, sz));
  ghost.visible = true;
  ghost.position.set(cx, 0, cz);
  ghost.traverse(o => { if (o.material @COMMENT_BODY@@COMMENT_BODY@ o.material.opacity !== undefined) o.material.opacity = 0.5; });
  // Показати колір зайнятості
  const occupiedNow = occupied.has(key(cx, cz)) || Math.abs(cx) > half || Math.abs(cz) > half;
  ghost.traverse(o => {
    if (o.isMesh @COMMENT_BODY@@COMMENT_BODY@ o.material.color) {
      o.material.emissive = new THREE.Color(occupiedNow ? 0x880000 : 0x000000);
    }
  });
});

function tryBuildOrDelete(cx, cy) {
  const p = getGroundPoint(cx, cy);
  if (!p) return;
  const sx = snap(p.x), sz = snap(p.z);
  const half = SIZE/2*GRID;
  if (Math.abs(sx) > half || Math.abs(sz) > half) { showMsg('❌ Поза межами міста'); return; }

  if (currentTool === 'delete') {
    const k = key(sx, sz);
    const idx = buildingsList.findIndex(b => b.key === k);
    if (idx >= 0) {
      const b = buildingsList[idx];
      scene.remove(b.obj);
      occupied.delete(k);
      money += Math.floor(COSTS[b.type] * 0.5);
      population -= POP[b.type];
      buildingsList.splice(idx, 1);
      updateUI();
      showMsg('🗑️ Знесено (+' + Math.floor(COSTS[b.type]*0.5) + ')');
    }
    return;
  }

  const k = key(sx, sz);
  if (occupied.has(k)) { showMsg('❌ Місце зайняте'); return; }
  const cost = COSTS[currentTool];
  if (money < cost) { showMsg('❌ Недостатньо грошей'); return; }

  const obj = BUILDERS[currentTool]();
  obj.position.set(sx, 0, sz);
  obj.rotation.y = Math.random() * Math.PI * 2;
  scene.add(obj);
  buildingsList.push({ obj, key: k, type: currentTool });
  occupied.add(k);
  money -= cost;
  population += POP[currentTool];

  // Анімація появи
  obj.scale.set(0.01, 0.01, 0.01);
  const start = performance.now();
  function anim() {
    const t = Math.min((performance.now() - start) / 400, 1);
    const e = 1 - Math.pow(1-t, 3);
    obj.scale.setScalar(e);
    if (t < 1) requestAnimationFrame(anim);
  }
  anim();

  updateUI();
  showMsg('✅ Побудовано! -' + cost);
}

// ═══════════ UI ═══════════
function updateUI() {
  document.getElementById('money').textContent = money;
  document.getElementById('buildings').textContent = buildingsList.length;
  document.getElementById('pop').textContent = population;
  happiness = Math.max(0, Math.min(100, 50 + buildingsList.length * 3 - Math.floor(population/5)));
  document.getElementById('happy').textContent = happiness + '%';
}

function showMsg(text) {
  const el = document.getElementById('msg');
  el.textContent = text;
  el.classList.add('show');
  clearTimeout(el._t);
  el._t = setTimeout(() => el.classList.remove('show'), 1500);
}

// Вибір інструмента
document.querySelectorAll('.tool').forEach(t => {
  t.addEventListener('click', () => {
    document.querySelectorAll('.tool').forEach(x => x.classList.remove('active'));
    t.classList.add('active');
    currentTool = t.dataset.type;
    updateGhost(currentTool);
  });
});

// ═══════════ КЛАВІАТУРА (WASD) ═══════════
const keys = {};
addEventListener('keydown', e => keys[e.key.toLowerCase()] = true);
addEventListener('keyup', e => keys[e.key.toLowerCase()] = false);

// ═══════════ РЕСАЙЗ ═══════════
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// ═══════════ АНІМАЦІЯ ═══════════
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const dt = clock.getDelta();
  const t = clock.getElapsedTime();

  // Рух камери WASD
  const speed = 30 * dt;
  const forward = new THREE.Vector3();
  camera.getWorldDirection(forward);
  forward.y = 0; forward.normalize();
  const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0,1,0));

  const move = new THREE.Vector3();
  if (keys['w']) move.add(forward);
  if (keys['s']) move.sub(forward);
  if (keys['d']) move.add(right);
  if (keys['a']) move.sub(right);
  if (move.lengthSq() > 0) {
    move.normalize().multiplyScalar(speed);
    camera.position.add(move);
    controls.target.add(move);
  }

  // Легке погойдування пальм
  buildingsList.forEach(b => {
    if (b.type === 'tree') {
      b.obj.rotation.z = Math.sin(t * 1.5 + b.obj.position.x) * 0.02;
    }
  });

  // Вода блищить
  MAT.water.roughness = 0.1 + Math.sin(t*2)*0.05;

  controls.update();
  renderer.render(scene, camera);
}

// ═══════════ ІНІЦІАЛІЗАЦІЯ ═══════════
updateGhost('house');
updateUI();
animate();

// Привітальне повідомлення
setTimeout(() => showMsg('🏜️ Ласкаво просимо до Ємену! Будуй місто'), 500);
</script>
